	router.GET(options.BaseURL+"/health", wrapper.GetHealth)
	router.POST(options.BaseURL+"/users", wrapper.CreateUser)
	router.POST(options.BaseURL+"/users/login", wrapper.LoginUser)
	router.POST(options.BaseURL+"/users/logout", wrapper.LogoutUser)
	router.GET(options.BaseURL+"/users/me", wrapper.GetMe)
	router.GET(options.BaseURL+"/users/:userId", wrapper.GetUser)
	router.GET(options.BaseURL+"/answers", wrapper.GetAnswers)
	router.PUT(options.BaseURL+"/answers/me", wrapper.PutMyAnswer)
	router.GET(options.BaseURL+"/polls/:date", wrapper.GetPoll)
	router.PUT(options.BaseURL+"/polls/:date", wrapper.UpdatePoll)
	router.POST(options.BaseURL+"/devices", wrapper.CreateDeviceToken)
	router.POST(options.BaseURL+"/admin/notifications", wrapper.SendNotification)
